local ContextActionService = game:GetService("ContextActionService")
local RunService = game:GetService("RunService")
local module = {}
local bindablefunc: BindableFunction = script.Parent.BindableFunction

local color1 = Color3.fromRGB(46, 46, 46)
local CONTENT = nil

local SCREENGUI = nil

local SELECTED_VM = nil
local SELECTED_MODEL = nil
local SELECTED_PROPERTY = nil


function module:Init()
    
    ContextActionService:BindActionAtPriority("NezaUI_Debugger", function(actionName, inputState, inputObject)
        if inputState == Enum.UserInputState.Begin then
            self:Toggle()
        end
    end, false, Enum.ContextActionPriority.High.Value + 1000, Enum.KeyCode.F10)

    self:CreateUI()
end

function module:CreateUI()
    local screenGui = Instance.new("ScreenGui")
    screenGui.Name = "NezaUI_Debugger"
    screenGui.Parent = game.Players.LocalPlayer:WaitForChild("PlayerGui")
    screenGui.ScreenInsets = Enum.ScreenInsets.TopbarSafeInsets
    screenGui.DisplayOrder = 10^6
    screenGui.Enabled = false

    local uilistlayout = Instance.new("UIListLayout", screenGui)
    uilistlayout.Padding = UDim.new(0, 5)
    uilistlayout.FillDirection = Enum.FillDirection.Vertical
    uilistlayout.SortOrder = Enum.SortOrder.LayoutOrder
    uilistlayout.VerticalAlignment = Enum.VerticalAlignment.Top
    uilistlayout.HorizontalAlignment = Enum.HorizontalAlignment.Left

    local uipadding = Instance.new("UIPadding", screenGui)
    uipadding.PaddingLeft = UDim.new(0, 10)

    local bar = Instance.new("Frame", screenGui)
    bar.Size = UDim2.new(1, 0, 1, 0)
    bar.BackgroundTransparency = 1
    bar.Name = "Bar"

    local barLayout = Instance.new("UIListLayout", bar)
    barLayout.Padding = UDim.new(0, 5)
    barLayout.FillDirection = Enum.FillDirection.Horizontal
    barLayout.SortOrder = Enum.SortOrder.LayoutOrder
    barLayout.VerticalAlignment = Enum.VerticalAlignment.Top
    barLayout.HorizontalAlignment = Enum.HorizontalAlignment.Left

    local barPadding = Instance.new("UIPadding", bar)
    barPadding.PaddingTop = UDim.new(0, 10)

    local openBtn = Instance.new("TextButton", bar)
    openBtn.BackgroundColor3 = color1
    openBtn.Size = UDim2.new(0, 100, 1, 0)
    openBtn.Text = "Neza"
    openBtn.TextColor3 = Color3.new(1, 1, 0)
    openBtn.TextSize = 20
    local openBtnCorner = Instance.new("UICorner", openBtn)
    openBtnCorner.CornerRadius = UDim.new(0, 12)
    openBtn.MouseButton1Click:Connect(function()
        if CONTENT:FindFirstChild("VM") then
            CONTENT.VM:Destroy()
            if CONTENT:FindFirstChild("M") then
                CONTENT.M:Destroy()
            end
        
            if CONTENT:FindFirstChild("P") then
                CONTENT.P:Destroy()
            end
            if CONTENT:FindFirstChild("V") then
                CONTENT.V:Destroy()
            end
        else
            self:_updateVmList()
        end
    end)

    local bottom = Instance.new("Frame", screenGui)
    bottom.Size = UDim2.new(1, 0, 0, 0)
    bottom.AutomaticSize = Enum.AutomaticSize.Y
    bottom.BackgroundTransparency = 1

    local bottomLayout = Instance.new("UIListLayout", bottom)
    bottomLayout.Padding = UDim.new(0, 5)
    bottomLayout.FillDirection = Enum.FillDirection.Horizontal
    bottomLayout.SortOrder = Enum.SortOrder.LayoutOrder
    bottomLayout.VerticalAlignment = Enum.VerticalAlignment.Top
    bottomLayout.HorizontalAlignment = Enum.HorizontalAlignment.Left

    CONTENT = bottom
    SCREENGUI = screenGui
end


local function newPanel()
    local frame = Instance.new("Frame")
    frame.BackgroundColor3 = color1
    frame.BackgroundTransparency = 1
    frame.AutomaticSize = Enum.AutomaticSize.XY

    local uilistlayout = Instance.new("UIListLayout", frame)
    uilistlayout.Padding = UDim.new(0, 0)
    uilistlayout.FillDirection = Enum.FillDirection.Vertical
    uilistlayout.SortOrder = Enum.SortOrder.LayoutOrder
    uilistlayout.VerticalAlignment = Enum.VerticalAlignment.Top
    uilistlayout.HorizontalAlignment = Enum.HorizontalAlignment.Left

    return frame
end

local function newNode(text)
    local textBtn = Instance.new("TextButton")
    textBtn.BackgroundColor3 = color1
    textBtn.BackgroundTransparency = 0.2
    textBtn.AutomaticSize = Enum.AutomaticSize.XY
    textBtn.BorderSizePixel = 0
    textBtn.Text = ""

    local uipadding = Instance.new("UIPadding", textBtn)
    uipadding.PaddingLeft = UDim.new(0, 10)
    uipadding.PaddingRight = UDim.new(0, 10)
    uipadding.PaddingTop = UDim.new(0, 10)
    uipadding.PaddingBottom = UDim.new(0, 10)

    local textLabel = Instance.new("TextLabel", textBtn)
    textLabel.Text = text or ""
    textLabel.TextColor3 = Color3.new(1, 1, 1)
    textLabel.BackgroundTransparency = 1
    textLabel.TextScaled = true
    textLabel.Size = UDim2.new(0, 150, 0, 25)
    textLabel.TextXAlignment = Enum.TextXAlignment.Left
    textLabel.BorderSizePixel = 0
    textLabel.Font = Enum.Font.ArialBold

    return textBtn
end

local function selectNode(list, node)
    for i, v in pairs(list:GetChildren()) do
        if v.Name ~= "_" and v:IsA("TextButton") then
            if v == node then
                v.BackgroundTransparency = 0
            else
                v.BackgroundTransparency = .2
            end
        end
    end
end

function module:_updateVmList(show)
    if CONTENT:FindFirstChild("VM") then
        CONTENT.VM:Destroy()
    end

    if CONTENT:FindFirstChild("M") then
        CONTENT.M:Destroy()
    end

    if CONTENT:FindFirstChild("P") then
        CONTENT.P:Destroy()
    end
    if CONTENT:FindFirstChild("V") then
        CONTENT.V:Destroy()
    end
    SELECTED_VM = nil
    
    local vms = {}

    for i, v in pairs(bindablefunc:Invoke("_getAllViewModels")) do
        if v:FindFirstChild("Model") and v.Model:IsA("Folder") then
            if not vms[i] then
                vms[i] = {}
            end
            for j, k in pairs(v.Model:GetChildren()) do
                if k:IsA("ModuleScript") then
                    table.insert(vms[i], k)
                end
            end
        end
    end

    for i, v in pairs(bindablefunc:Invoke("_getAllGlobalModels")) do
        if not vms["_global"] then
            vms["_global"] = {}
        end
        table.insert(vms["_global"], v)
    end

    local list = newPanel()
    list.Name = "VM"
    list.Parent = CONTENT
    list.LayoutOrder = 1

    local idx = 0
    for i, v in pairs(vms) do
        idx = idx + 1
        local vmNode = newNode(i)
        vmNode.Parent = list
        vmNode.LayoutOrder = idx
        vmNode.Name = i

        vmNode.MouseButton1Click:Connect(function()
            local models = {}
            for j, k in pairs(v) do
                models[k.Name] = k
            end

            if SELECTED_VM == vmNode.Name then
                SELECTED_VM = nil
                self:_updateModelList(nil, vmNode.LayoutOrder)
                selectNode(list, nil)
            else
                SELECTED_VM = vmNode.Name
                self:_updateModelList(models, vmNode.LayoutOrder)
                selectNode(list, vmNode)
            end

            -- if v:FindFirstChild("Model") and v.Model:IsA("Folder") then
            --     local models = {}
            --     for i, v in pairs(v.Model:GetChildren()) do
            --         if v:IsA("ModuleScript") then
            --             models[v.Name] = v
            --         end
            --     end
            --     if SELECTED_VM == vmNode.Name then
            --         SELECTED_VM = nil
            --         self:_updateModelList(nil, vmNode.LayoutOrder)
            --         selectNode(list, nil)
            --     else
            --         SELECTED_VM = vmNode.Name
            --         self:_updateModelList(models, vmNode.LayoutOrder)
            --         selectNode(list, vmNode)
            --     end
            -- end
        end)
    end
    if list:FindFirstChild("_global") then
        list._global.LayoutOrder = 1
        local idx = 1
        for i, v in pairs(list:GetChildren()) do
            if v:IsA("TextButton") and v.Name ~= "_global" then
                idx += 1
                v.LayoutOrder = idx
            end
        end
    end
end

function module:_updateModelList(models, idx)
    if CONTENT:FindFirstChild("M") then
        CONTENT.M:Destroy()
    end

    if CONTENT:FindFirstChild("P") then
        CONTENT.P:Destroy()
    end
    if CONTENT:FindFirstChild("V") then
        CONTENT.V:Destroy()
    end
    SELECTED_MODEL = nil
    if not models then
        return
    end

    local list = newPanel()
    list.Name = "M"
    list.Parent = CONTENT
    list.LayoutOrder = 2

    for i = 1, idx do
        

        local blank
        if i == idx then
            blank = newNode("< Model >")
            blank.TextLabel.TextColor3 = Color3.new(.6, 0.6, 0.6)
            blank.TextLabel.TextXAlignment = Enum.TextXAlignment.Center
        else
            blank = newNode()
        end

        blank.Parent = list
        blank.LayoutOrder = -1
        blank.AutoButtonColor = false
        blank.Name = "_"
    end

    for i, v in pairs(models) do
        idx = idx + 1
        local modelNode = newNode(i)
        modelNode.Parent = list
        modelNode.LayoutOrder = idx
        modelNode.Name = i

        modelNode.MouseButton1Click:Connect(function()
            if SELECTED_MODEL == modelNode.Name then
                SELECTED_MODEL = nil
                self:_updatePropertyList(nil, modelNode.LayoutOrder)
                selectNode(list, nil)
            else
                SELECTED_MODEL = modelNode.Name
                self:_updatePropertyList(require(v), modelNode.LayoutOrder)
                selectNode(list, modelNode)
            end
        end)
    end
end

function module:_updatePropertyList(model, idx)
    if CONTENT:FindFirstChild("P") then
        CONTENT.P:Destroy()
    end
    if CONTENT:FindFirstChild("V") then
        CONTENT.V:Destroy()
    end
    SELECTED_PROPERTY = nil
    if not model then
        return
    end

    local list = newPanel()
    list.Name = "P"
    list.Parent = CONTENT
    list.LayoutOrder = 3

    for i = 1, idx do
        local blank
        if i == idx then
            blank = newNode("< Property >")
            blank.TextLabel.TextColor3 = Color3.new(.6, 0.6, 0.6)
            blank.TextLabel.TextXAlignment = Enum.TextXAlignment.Center
        else
            blank = newNode()
        end

        blank.Parent = list
        blank.LayoutOrder = -1
        blank.AutoButtonColor = false
        blank.Name = "_"
    end
    local properties = model:GetData()
    for i, v in pairs(properties) do
        if typeof(v) == "function" then
            continue
        end
        idx = idx + 1
        local propertyNode = newNode(i)
        propertyNode.Parent = list
        propertyNode.LayoutOrder = idx
        propertyNode.Name = i

        propertyNode.MouseButton1Click:Connect(function()
            if SELECTED_PROPERTY == propertyNode.Name then
                SELECTED_PROPERTY = nil
                self:_updateValue(nil, propertyNode.LayoutOrder)
                selectNode(list, nil)
            else
                SELECTED_PROPERTY = propertyNode.Name
                self:_updateValue(model, i, propertyNode.LayoutOrder)
                selectNode(list, propertyNode)
            end
        end)
    end
end

function module:_updateValue(model, key, idx)
    if CONTENT:FindFirstChild("V") then
        CONTENT.V:Destroy()
    end

    if not model then
        return
    end

    local list = newPanel()
    list.Name = "V"
    list.Parent = CONTENT
    list.LayoutOrder = 4

    local title
    for i = 1, idx do
        local blank
        if i == idx then
            blank = newNode("< Value >")
            blank.TextLabel.TextColor3 = Color3.new(.6, 0.6, 0.6)
            blank.TextLabel.TextXAlignment = Enum.TextXAlignment.Center
            title = blank
        else
            blank = newNode()
        end

        blank.Parent = list
        blank.LayoutOrder = -1
        blank.AutoButtonColor = false
        blank.Name = "_"
    end

    local str = model[key]
    if typeof(str) == "table" then
        str = game:GetService("HttpService"):JSONEncode(str)
    end
    str = tostring(str)
    
    local valueNode = newNode(str)
    valueNode.Parent = list
    valueNode.LayoutOrder = idx + 1
    valueNode.Name = "V"

    local connection
    connection = RunService.RenderStepped:Connect(function()
        if not valueNode or not valueNode.Parent or not SELECTED_PROPERTY then
            if CONTENT:FindFirstChild("E") then
                CONTENT.E:Destroy()
            end
            connection:Disconnect()
            return
        end
        local str = model[key]
        if typeof(str) == "table" then
            str = game:GetService("HttpService"):JSONEncode(str)
        end
        title.TextLabel.Text = `< {typeof(model[key])} >`
        valueNode.TextLabel.Text = tostring(str)
    end)

    valueNode.MouseButton1Click:Connect(function()
        self:_updateEdit(model, key, valueNode.LayoutOrder)
    end)
end

local function getEditNode(t)
    local frame = Instance.new("Frame")
    frame.BackgroundColor3 = color1
    frame.BackgroundTransparency = .2
    frame.AutomaticSize = Enum.AutomaticSize.XY

    local uilistlayout = Instance.new("UIListLayout", frame)
    uilistlayout.Padding = UDim.new(0, 5)
    uilistlayout.FillDirection = Enum.FillDirection.Vertical
    uilistlayout.SortOrder = Enum.SortOrder.LayoutOrder
    uilistlayout.VerticalAlignment = Enum.VerticalAlignment.Top
    uilistlayout.HorizontalAlignment = Enum.HorizontalAlignment.Left

    local uipadding = Instance.new("UIPadding", frame)
    uipadding.PaddingLeft = UDim.new(0, 10)
    uipadding.PaddingRight = UDim.new(0, 10)
    uipadding.PaddingTop = UDim.new(0, 10)
    uipadding.PaddingBottom = UDim.new(0, 10)

    local textBox = Instance.new("TextBox", frame)
    textBox.Text = t
    textBox.TextColor3 = Color3.new(1, 1, 1)
    textBox.TextSize = 22
    textBox.BackgroundTransparency = .2
    textBox.BackgroundColor3 = color1
    textBox.Size = UDim2.new(0, 150, 0, 200)
    textBox.ClearTextOnFocus = false
    textBox.TextWrapped = true
    textBox.MultiLine = true
    textBox.TextXAlignment = Enum.TextXAlignment.Left
    textBox.AutomaticSize = Enum.AutomaticSize.Y
    textBox.Font = Enum.Font.ArialBold
    
    local confirmBtn = newNode("Confirm")
    confirmBtn.Parent = frame
    confirmBtn.BackgroundColor3 = Color3.fromRGB(0, 170, 0)
    confirmBtn.UIPadding.PaddingLeft = UDim.new(0, 0)
    confirmBtn.UIPadding.PaddingRight = UDim.new(0, 0)
    confirmBtn.TextLabel.TextXAlignment = Enum.TextXAlignment.Center
    confirmBtn.Name = "Confirm"

    textBox:GetPropertyChangedSignal("Text"):Connect(function()
        confirmBtn.TextLabel.Text = "Confirm"
        confirmBtn.BackgroundColor3 = Color3.fromRGB(0, 170, 0)
    end)

    return frame
end

function module:_updateEdit(model, key, idx)
    if CONTENT:FindFirstChild("E") then
        CONTENT.E:Destroy()
    end

    local list = newPanel()
    list.Name = "E"
    list.Parent = CONTENT
    list.LayoutOrder = 5

    local title
    for i = 1, idx do
        local blank
        if i == idx then
            blank = newNode("< Edit >")
            blank.TextLabel.TextColor3 = Color3.new(.6, 0.6, 0.6)
            blank.TextLabel.TextXAlignment = Enum.TextXAlignment.Center
            title = blank
        else
            blank = newNode()
        end

        blank.Parent = list
        blank.LayoutOrder = -1
        blank.AutoButtonColor = false
        blank.Name = "_"
        blank.TextLabel.AutomaticSize = Enum.AutomaticSize.X

    end
    local str = model[key]
    if typeof(str) == "table" then
        str = game:GetService("HttpService"):JSONEncode(str)
    end
    str = tostring(str)

    local editNode = getEditNode(str)
    editNode.Parent = list

    editNode.Confirm.MouseButton1Click:Connect(function()
        local newStr = editNode.TextBox.Text
        
        local str = model[key]
        if typeof(str) == "table" then
            str = game:GetService("HttpService"):JSONEncode(str)
        end
        str = tostring(str)

        if newStr == str then
            return
        end

        local suc = pcall(function()
            if typeof(model[key]) == "number" then
                newStr = newStr - 0
                model[key] = newStr
            elseif typeof(model[key]) == "boolean" then
                newStr = string.lower(newStr) == "true"
                model[key] = newStr
            elseif typeof(model[key]) == "table" then
                newStr = game:GetService("HttpService"):JSONDecode(newStr)
                model[key] = newStr
            end
        end)
        if suc then
            editNode.Confirm.TextLabel.Text = "Success"
        else
            editNode.Confirm.TextLabel.Text = "Failed"
            editNode.Confirm.BackgroundColor3 = Color3.fromRGB(170, 0, 0)
        end
    end)
end

function module:Toggle()
    SCREENGUI.Enabled = not SCREENGUI.Enabled
end

return module